def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [a for a, b in history]
    opp = [b for a, b in history]
    last_my = my[-1]
    last_opp = opp[-1]

    total_opp_d = 0
    for o in opp:
        if o == 'D':
            total_opp_d += 1

    total_my_d = 0
    for m in my:
        if m == 'D':
            total_my_d += 1

    opp_d_run = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        opp_d_run += 1
        i -= 1

    my_d_run = 0
    i = n - 1
    while i >= 0 and my[i] == 'D':
        my_d_run += 1
        i -= 1

    cd_run = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        if my[i] == 'C':
            cd_run += 1
        i -= 1

    rc = min(n, 12)
    start = n - rc
    r_opp_d = 0
    r_cd = 0
    for i in range(start, n):
        if opp[i] == 'D':
            r_opp_d += 1
        if my[i] == 'C' and opp[i] == 'D':
            r_cd += 1

    our_d = 0
    retaliated = 0
    for i in range(n - 1):
        if my[i] == 'D':
            our_d += 1
            if opp[i + 1] == 'D':
                retaliated += 1

    hard_defect = (
        opp_d_run >= 12
        or (n >= 12 and r_opp_d >= max(6, rc - 1))
        or (n >= 12 and total_opp_d * 20 > 11 * n)
        or (opp_d_run >= 6 and r_cd >= 5)
    )

    if last_opp == 'D':
        if hard_defect:
            return 'D'

        if my_d_run == 0:
            if n >= 2 and my[-2] == 'D':
                if n <= 60 and opp_d_run <= 5 and r_cd <= 3 and total_opp_d * 5 <= 3 * n:
                    return 'C'
                if opp_d_run <= 3 and r_cd <= 1 and total_opp_d * 5 <= 3 * n:
                    return 'C'

            if (opp_d_run == 1 and n <= 60 and
                total_opp_d <= max(1, n // 10) and
                r_cd <= max(1, rc // 6)):
                return 'C'

            return 'D'

        if cd_run == 0:
            target = 2
        elif cd_run == 1:
            target = min(4, max(2, (opp_d_run - cd_run) + 1))
        elif cd_run == 2:
            target = min(4, max(2, opp_d_run - cd_run))
        else:
            target = min(4, max(3, opp_d_run - cd_run))

        if target < 2:
            target = 2
        if target > 4:
            target = 4

        if my_d_run >= target and r_cd <= 2 and not (n >= 85 and opp_d_run >= 4):
            return 'C'

        return 'D'

    if n >= 98 and our_d > 0 and retaliated == 0 and total_opp_d <= 3 and r_opp_d == 0:
        return 'D'

    if (last_my == 'D' and our_d > 0 and
        retaliated * 3 <= our_d and
        r_opp_d >= 3):
        return 'D'

    return 'C'
